head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf15000";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — resultList, applProcsTpCd

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "ul_107", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("<br/> 총 <strong id=\"totPage\">" + String(dma_page.get("total")) + "</strong>건 <span id=\"totPage1\">(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_resultList", fn: function(){ return (!(String(((dma_pageContext.get("resultList") ?? "")) == null ? '' : ((dma_pageContext.get("resultList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return " " + String(String((dma_pageContext.get("comNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return " " + String(String((dma_pageContext.get("isurCd") ?? ""))); } },
        { childId: "cal_startDate", fn: function () { return String((dma_pageContext.get("startDate") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_startDate
 * @description 초기화 — datefmt cal start Date
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_startDate = function () { $c.date.checkCalendarFormat("cal_startDate", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_endDate
 * @description 초기화 — datefmt cal end Date
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_endDate = function () { $c.date.checkCalendarFormat("cal_endDate", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const applProcsTpCd = (String(((dma_pageContext.get("applProcsTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("applProcsTpCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("applProcsTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("applProcsTpCd") ?? ""))));
        if (applProcsTpCd !== "") {
            $c.util.getComponent('slc_applProcsTpCd').setValue(applProcsTpCd);
        }
        const kind = "" + dma_pageContext.get("kind") + "";
        if (kind.length === 0) {
            const fm = (document.JLDINF15000 || { elements: [] });
            $c.util.getComponent("ipt_checkBox").setValue(true);
            scwin.SetChecked(fm);
        } else {
            for (let i = 0; i < kind.length; i++) {
                $("#kind_" + kind.substr(i, 1)).attr("checked", true);
            }
        }
        const pageIndex = $c.util.getComponent('ipt_currentPage').getValue();
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf15000.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":3
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf15000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_datefmt_cal_startDate();
        scwin.init_datefmt_cal_endDate();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf15000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_checkBox_onclick
 * @description 「0」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_checkBox_onclick = function(e){
    try {
        scwin.SetChecked('__self.form')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf15000.ipt_checkBox_onclick' }); }
};

/**
 * @method
 * @name btn_appDate2_onclick
 * @description btn_appDate2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_onclick = function(e){
    try {
        scwin.appDate2('startDate','endDate',3)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf15000.btn_appDate2_onclick' }); }
};

/**
 * @method
 * @name btn_appDate2_2_onclick
 * @description btn_appDate2_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_2_onclick = function(e){
    try {
        scwin.appDate2('startDate','endDate',6)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf15000.btn_appDate2_2_onclick' }); }
};

/**
 * @method
 * @name btn_appDate2_3_onclick
 * @description btn_appDate2_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_appDate2_3_onclick = function(e){
    try {
        scwin.appDate2('startDate','endDate',12)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf15000.btn_appDate2_3_onclick' }); }
};

/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf15000.btn_search_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["stdCdGrntFeeProcsStatCd"] === '2' && r["stdCdGrntFeeProcsStatCd"] !== '' && (r["applProcsTpCd"] === '0' || r["applProcsTpCd"] === '3')) { await scwin.print(r["isuNm"], r["stdCdApplContnTpNm"], r["applDate"], r["stdCdGrntFee"], r["asumAcntNoFmtHyp"]); return; } return; } if (r["stdCdProcsTpCd"] === '1') { scwin.popupCode3(r["stdCdApplContnTpCd"], r["stdCdApplId"], r["cpBndTpCd"]); return; }
        if (r["applProcsTpCd"] === '2' && r["stdCdApplContnTpCd"] !== '08' && r["stdCdProcsTpCd"] === '1' && r["retApplId"] === '') { await scwin.returnAppl(r["stdCdApplContnTpCd"], r["stdCdApplId"], r["cpBndTpCd"], r["retRsn"], r["asumAcntNo"], r["stdCdGrntFeeProcsStatCd"]); return; }
        scwin.popupCode2(r["stdCdApplContnTpCd"], r["stdCd"], r["cpBndTpCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/stdcd/stdcdNewReqList.do?method=stdcdNewReqList&pageDiv=",
        ref: "dma_searchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_print
 * @description print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/stdcd/stdcdNewReqList.do?method=stdcdNewReqList&pageDiv=",
        ref: "dma_loadListReq",
        target: "dlt_applProcsTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_216").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appDate2
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {String} startId startId
 * @param {String} endId endId
 * @param {*} months months
 * @returns {void}
 * @hidden N
 */
scwin.appDate2 = function (startId, endId, months) { try { const end = $c.date.getServerDateTime(); const start = $c.date.addMonth(end, -Number(months || 0)); const r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const s = r(String(startId)); if (s && s.setValue) { s.setValue(start); } const e2 = r(String(endId)); if (e2 && e2.setValue) { e2.setValue(end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

/**
 * @method
 * @name grd_resultList_fmt_applDate
 * @description grd result List fmt appl Date 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_applDate = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "stdCdProcsTpCd") ?? '') : '');
        if (v === '1') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "applDate") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "applDate") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.applDate" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_resultList_fmt_stdCdApplContnTpNm
 * @description grd result List fmt std Cd Appl Contn Tp Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_stdCdApplContnTpNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "stdCdApplContnTpCd") ?? '') : '');
        if (v === '04') { return "WR"; }
        if (v === '05') { return "R"; }
        if (v === '06') { return "DR"; }
        if (v === '09') { return "CD"; }
        if (v === '10') { return "ELW"; }
        if (v === '11') { return "ELS/DLS..."; }
        if (v === '12') { return "ETN"; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "stdCdApplContnTpNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.stdCdApplContnTpNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_resultList_fmt_asumAcntNoFmtAst
 * @description grd result List fmt asum Acnt No Fmt Ast 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_asumAcntNoFmtAst = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "depoYn") ?? '') : '');
        if (v === 'Y') { return String((dl && dl.getCellData ? dl.getCellData(r, "asumAcntNoFmtAst") : '') ?? ''); }
        return String((dl && dl.getCellData ? dl.getCellData(r, "asumAcntNoFmtAst") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.asumAcntNoFmtAst" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_resultList_fillAct
 * @description grd result List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.fillAct' });
    }
};

/**
 * @method
 * @name SetChecked
 * @description Set Checked 처리
 * @param {*} fm fm
 * @returns {void}
 * @hidden N
 */
scwin.SetChecked = function (fm) {
    if ((String($c.util.getComponent('ipt_checkBox').getValue() || "") !== "")) {
        $c.util.getComponent("ipt_kind2").setValue(true);
        $c.util.getComponent("ipt_kind1").setValue(true);
        $c.util.getComponent("ipt_kind3").setValue(true);
        $c.util.getComponent("ipt_kind4").setValue(true);
        $c.util.getComponent("ipt_kind5").setValue(true);
        $c.util.getComponent("ipt_kind9").setValue(true);
        $c.util.getComponent("ipt_kind7").setValue(true);
        $c.util.getComponent("ipt_kind6").setValue(true);
        $c.util.getComponent("ipt_kind8").setValue(true);
        $c.util.getComponent("ipt_kind_A").setValue(true);
        $c.util.getComponent("ipt_kind_B").setValue(true);
        $c.util.getComponent("ipt_kind_C").setValue(true);
        $c.util.getComponent("ipt_kind_D").setValue(true);
    } else {
        $c.util.getComponent("ipt_kind2").setValue(false);
        $c.util.getComponent("ipt_kind1").setValue(false);
        $c.util.getComponent("ipt_kind3").setValue(false);
        $c.util.getComponent("ipt_kind4").setValue(false);
        $c.util.getComponent("ipt_kind5").setValue(false);
        $c.util.getComponent("ipt_kind9").setValue(false);
        $c.util.getComponent("ipt_kind7").setValue(false);
        $c.util.getComponent("ipt_kind6").setValue(false);
        $c.util.getComponent("ipt_kind8").setValue(false);
        $c.util.getComponent("ipt_kind_A").setValue(false);
        $c.util.getComponent("ipt_kind_B").setValue(false);
        $c.util.getComponent("ipt_kind_C").setValue(false);
        $c.util.getComponent("ipt_kind_D").setValue(false);
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} pageDiv pageDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (pageDiv) {
    let kind;
    const fm = (document.JLDINF15000 || { elements: [] });
    kind = "";
    if ((String($c.util.getComponent('ipt_kind2').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind2').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind1').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind1').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind3').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind3').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind4').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind4').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind5').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind5').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind9').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind9').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind7').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind7').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind6').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind6').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind8').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind8').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind_A').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind_A').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind_B').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind_B').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind_C').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind_C').getValue();
    }
    if ((String($c.util.getComponent('ipt_kind_D').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_kind_D').getValue();
    }
    if (kind === "") {
        await $c.win.alert('상품 구분을 선택하세요');
        return;
    }
    if (($c.util.getComponent('cal_startDate').getValue() == null ? '' : String($c.util.getComponent('cal_startDate').getValue())) !== '' && ($c.util.getComponent('cal_endDate').getValue() == null ? '' : String($c.util.getComponent('cal_endDate').getValue())) !== '') {
        if ($c.util.getComponent('cal_startDate').getValue()> $c.util.getComponent('cal_endDate').getValue()) {
            await $c.win.alert('종료일은 시작일 이후로 입력하세요');
            $c.util.getComponent("cal_endDate").focus();
            return;
        }
    }
    if (pageDiv === "1") {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    $c.util.getComponent('dma_searchReq').set('kind', kind);
    fm.action = "/stdcd/stdcdNewReqList.do?method=stdcdNewReqList&pageDiv=" + pageDiv;
    fm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
};

