/**
 * @method
 * @name print
 * @description print 처리
 * @param {*} isu_nm isu_nm
 * @param {*} std_cd_appl_contn_tp_nm std_cd_appl_contn_tp_nm
 * @param {*} appl_date appl_date
 * @param {*} std_cd_grnt_fee std_cd_grnt_fee
 * @param {*} asum_acnt_no asum_acnt_no
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function (isu_nm, std_cd_appl_contn_tp_nm, appl_date, std_cd_grnt_fee, asum_acnt_no) {
    if (asum_acnt_no === "" || asum_acnt_no == null) {
        asum_acnt_no = "";
    } else {
        asum_acnt_no = "신한은행 " + asum_acnt_no + " (한국거래소)";
    }
    $c.util.getComponent('dma_searchReq').set('comNm', $c.util.getComponent("dma_searchReq").get("comNm"));
    $c.util.getComponent('dma_searchReq').set('isuNm', isu_nm);
    $c.util.getComponent('dma_searchReq').set('stdCdTpNm', std_cd_appl_contn_tp_nm);
    $c.util.getComponent('dma_searchReq').set('curDate', appl_date);
    $c.util.getComponent('dma_searchReq').set('grntFee', std_cd_grnt_fee);
    $c.util.getComponent('dma_searchReq').set('asumAcntNo', asum_acnt_no);
    await scwin.tx_fn_print();
};

