/**
 * @method
 * @name krxpage_pagenavigator_216_onclick
 * @description krxpage_pagenavigator_216 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_216_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_loadListReq').set('pageIndex', pi);
        await scwin.tx_load_list();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldinf15000.krxpage_pagenavigator_216_onclick" });
    }
};
